do $ctrl$
declare n integer;
begin
  select count(*) into n from lot_v3 where payload is null or name is null or short_description is null;
  if n > 0 then raise exception '% lignes incompletes : dictionnaire non charge.', n; end if;
end $ctrl$;

-- Aucune ecriture dans `prompt_media` : sans visuel, la carte affiche son
-- cadre par defaut. C'est aussi la garantie qu'aucun envoi fait depuis
-- l'administration ne peut etre ecrase par ce lot.
insert into public.prompts (
  external_ref, command, slug, name, mode, category_id, short_description, result_summary,
  intention, use_cases, tags, expected_input, minimal_context, sufficient_context,
  required_variables, optional_variables, default_values, expected_output, output_format,
  quality_criteria, preserve_rules, avoid_rules, limitations, usage_conditions,
  fallback_if_incomplete, blocking_condition, questionnaire_mode, max_questions,
  input_type, output_type, risk_level, priority, is_featured, show_image_card,
  card_image_mode, thumbnail_spec, default_image_alt, legacy_category, legacy_subcategory,
  sort_order, usage_example, test_nominal, test_incomplete_context, test_blocking,
  catalog_version, source_status, revised_at, is_new, status, published_at)
select
  l.external_ref, l.command::extensions.citext, l.slug, l.name, l.mode::public.app_mode, c.id,
  l.short_description, l.result_summary, l.intention, l.use_cases, l.tags,
  l.expected_input, l.minimal_context, l.sufficient_context,
  l.required_variables, l.optional_variables, l.default_values, l.expected_output,
  l.output_format, l.quality_criteria, l.preserve_rules, l.avoid_rules, l.limitations,
  l.usage_conditions, l.fallback_if_incomplete, l.blocking_condition, l.questionnaire_mode,
  l.max_questions, l.input_type::public.input_type, l.output_type::public.output_type,
  l.risk_level::public.risk_level, l.priority, l.is_featured, l.show_image_card,
  l.card_image_mode::public.card_image_mode, l.thumbnail_spec, l.default_image_alt,
  l.legacy_category, l.legacy_subcategory, l.sort_order, l.usage_example,
  l.test_nominal, l.test_incomplete_context, l.test_blocking,
  'v3.0', 'new_v3', date '2026-09-08', true, 'published'::public.content_status, now()
from lot_v3 l
join public.categories c on c.external_ref = l.family_ref
on conflict (external_ref) do update
  set command = excluded.command, slug = excluded.slug, name = excluded.name,
      mode = excluded.mode, category_id = excluded.category_id,
      short_description = excluded.short_description, result_summary = excluded.result_summary,
      intention = excluded.intention, use_cases = excluded.use_cases, tags = excluded.tags,
      expected_input = excluded.expected_input, minimal_context = excluded.minimal_context,
      sufficient_context = excluded.sufficient_context,
      required_variables = excluded.required_variables,
      optional_variables = excluded.optional_variables, default_values = excluded.default_values,
      expected_output = excluded.expected_output, output_format = excluded.output_format,
      quality_criteria = excluded.quality_criteria, preserve_rules = excluded.preserve_rules,
      avoid_rules = excluded.avoid_rules, limitations = excluded.limitations,
      usage_conditions = excluded.usage_conditions,
      fallback_if_incomplete = excluded.fallback_if_incomplete,
      blocking_condition = excluded.blocking_condition,
      questionnaire_mode = excluded.questionnaire_mode, max_questions = excluded.max_questions,
      input_type = excluded.input_type, output_type = excluded.output_type,
      risk_level = excluded.risk_level, priority = excluded.priority,
      is_featured = excluded.is_featured, show_image_card = excluded.show_image_card,
      card_image_mode = excluded.card_image_mode, thumbnail_spec = excluded.thumbnail_spec,
      default_image_alt = excluded.default_image_alt, legacy_category = excluded.legacy_category,
      legacy_subcategory = excluded.legacy_subcategory, sort_order = excluded.sort_order,
